SELECT

FROM User a WHERE 1 = 1

    AND a.uid = #{uid}


    AND a.userName LIKE CONCAT('%',#{userName}, '%')


    AND a.avatar LIKE CONCAT('%',#{avatar}, '%')


    AND a.loginPwd LIKE CONCAT('%',#{loginPwd}, '%')


    AND a.tradePwd LIKE CONCAT('%',#{tradePwd}, '%')


    AND a.email LIKE CONCAT('%',#{email}, '%')


    AND a.country LIKE CONCAT('%',#{country}, '%')


    AND a.mobileNo LIKE CONCAT('%',#{mobileNo}, '%')


    AND a.gaAuthKey LIKE CONCAT('%',#{gaAuthKey}, '%')


    AND a.location LIKE CONCAT('%',#{location}, '%')


    AND a.state = #{state}


    AND a.thawTime = #{thawTime}


    AND a.securityPolicy = #{securityPolicy}


    AND a.tradePolicy = #{tradePolicy}


    AND a.inviteCode LIKE CONCAT('%',#{inviteCode}, '%')


    AND a.referralCode LIKE CONCAT('%',#{referralCode}, '%')


    AND a.source LIKE CONCAT('%',#{source}, '%')


    AND a.riskEvaluation = #{riskEvaluation}


    AND a.certState = #{certState}


    AND a.lang = #{lang}


    AND a.localCurrency = #{localCurrency}


    AND a.stableCoinPreference = #{stableCoinPreference}


    AND a.remark = #{userLevel}


    AND a.remark = #{remark}

